use std::fmt;

struct Id(u32);

impl fmt::Display for Id {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(f, "#{}", self.0)
    }
}

fn main() {
    let id = Id(42);
    println!("{} {}", id, id.to_string().len());
}

#[derive(Debug, PartialEq, Eq, PartialOrd, Ord)]
struct Card {
    rank: u8,
    suit: char,
}

fn main() {
    let mut cards = vec![
        Card { rank: 3, suit: 'b' },
        Card { rank: 3, suit: 'a' },
        Card { rank: 1, suit: 'z' },
    ];
    cards.sort();
    println!("{} {}", cards[0].suit, cards[1].suit);
}

use std::ops::Add;

#[derive(Debug, Clone, Copy)]
struct Money(u32);

impl Add for Money {
    type Output = Money;
    fn add(self, o: Money) -> Money {
        Money(self.0 + o.0)
    }
}

impl From<u32> for Money {
    fn from(n: u32) -> Money {
        Money(n * 100)
    }
}

fn main() {
    let a: Money = 2.into();
    let b = Money(5);
    println!("{:?}", a + b);
}
